@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const open=id=>{const d=document.getElementById(id);if(d&&!d.open)d.showModal()};document.querySelectorAll('[data-sheet-open]').forEach(x=>x.onclick=()=>open(x.dataset.sheetOpen));document.querySelectorAll('[data-sheet-close]').forEach(x=>x.onclick=()=>document.getElementById(x.dataset.sheetClose)?.close());document.querySelectorAll('.form-sheet').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d)d.close()})});@if(request()->boolean('create') || old('_form_mode')==='createOrganization')open('create-organization-sheet');@endif @if($editingOrganization || old('_form_mode')==='editOrganization')open('edit-organization-sheet');@endif
document.querySelectorAll('[data-geographic-form]').forEach(f=>{
 const s=f.querySelector('[data-country-select]'),q=f.querySelector('[data-country-search]'),l=f.querySelector('[data-country-label]'),access=f.querySelector('[data-access-type]'),picker=f.querySelector('[data-country-picker]'),options=f.querySelector('[data-country-options]'),chips=f.querySelector('[data-country-chips]'),count=f.querySelector('[data-country-count]'),pickerLabel=f.querySelector('[data-country-picker-label]'),act=f.querySelector('[data-activation-mode]');
 const summary=()=>{f.querySelector('[data-summary-name]').textContent=f.querySelector('[name=name]')?.value||'À renseigner';f.querySelector('[data-summary-access]').textContent=access.value==='multi_country'?'Multipays':'Unipays';f.querySelector('[data-summary-countries]').textContent=[...s.selectedOptions].map(o=>o.text.split(' · ')[0]).join(', ')||'À sélectionner';f.querySelector('[data-summary-language]').textContent=f.querySelector('[name=default_language]')?.selectedOptions[0]?.text||'À renseigner';const a=f.querySelector('[data-summary-admin]');if(a)a.textContent=((f.querySelector('[name=admin_first_name]')?.value||'')+' '+(f.querySelector('[name=admin_last_name]')?.value||'')).trim()||'À renseigner'};
 const render=()=>{const selected=[...s.selectedOptions];count.textContent=`${selected.length} pays sélectionné${selected.length>1?'s':''}`;pickerLabel.textContent=selected.length?selected.map(o=>o.text.split(' · ')[0]).join(', '):(access.value==='multi_country'?'Sélectionner les pays':'Sélectionner un pays');chips.innerHTML='';selected.forEach(o=>{const chip=document.createElement('span');chip.className='country-chip';chip.append(document.createTextNode(o.text.split(' · ')[0]));const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.onclick=()=>{o.selected=false;render()};chip.append(remove);chips.append(chip)});summary()};
 [...s.options].forEach(o=>{const row=document.createElement('label');row.className='country-picker-option';row.dataset.search=o.text.toLowerCase();const box=document.createElement('input');box.type='checkbox';box.checked=o.selected;box.onchange=()=>{const checked=box.checked;if(checked&&access.value==='single_country'){[...s.options].forEach(x=>x.selected=false);options.querySelectorAll('input').forEach(x=>x.checked=false)}o.selected=checked;box.checked=checked;render()};row.append(box,document.createTextNode(o.text));options.append(row)});
 const refresh=()=>{const multi=access.value==='multi_country';l.textContent=multi?'Pays autorisés *':'Pays principal *';if(!multi&&s.selectedOptions.length>1)[...s.options].forEach((o,i)=>o.selected=i===0);options.querySelectorAll('input').forEach((box,i)=>box.checked=s.options[i].selected);render()};
 f.querySelector('[data-country-picker-trigger]')?.addEventListener('click',()=>picker.hidden=!picker.hidden);f.querySelector('[data-country-picker-close]')?.addEventListener('click',()=>picker.hidden=true);q?.addEventListener('input',()=>options.querySelectorAll('.country-picker-option').forEach(row=>row.hidden=!row.dataset.search.includes(q.value.toLowerCase())));access.addEventListener('change',refresh);f.querySelectorAll('input,select').forEach(x=>x.addEventListener('input',summary));f.querySelectorAll('[data-password-toggle]').forEach(button=>button.addEventListener('click',()=>{const input=button.parentElement.querySelector('input'),visible=input.type==='text';input.type=visible?'password':'text';button.querySelector('span').textContent=visible?'visibility':'visibility_off';button.ariaLabel=visible?'Afficher le mot de passe':'Masquer le mot de passe'}));const pass=()=>f.querySelectorAll('[data-password-field]').forEach(x=>{x.hidden=act?.value==='invitation';x.querySelector('input').required=act?.value!=='invitation'});act?.addEventListener('change',pass);pass();refresh()
});
const rows=[...document.querySelectorAll('[data-org-row]')],search=document.querySelector('[data-org-search]'),country=document.querySelector('[data-org-country]'),access=document.querySelector('[data-org-access]'),status=document.querySelector('[data-org-status]'),empty=document.querySelector('.pc-no-results');const filter=()=>{let n=0;rows.forEach(r=>{const ok=(!search.value||r.dataset.search.includes(search.value.toLowerCase()))&&(!country.value||r.dataset.country.includes(country.value.toLowerCase()))&&(!access.value||r.dataset.access===access.value)&&(!status.value||r.dataset.status===status.value);r.hidden=!ok;if(ok)n++});if(empty)empty.hidden=n>0};[search,country,access,status].forEach(x=>x?.addEventListener('input',filter));document.querySelector('[data-org-reset]')?.addEventListener('click',()=>{[search,country,access,status].forEach(x=>x.value='');filter()});});
</script>@endpush
